import { TriangleAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import Callout from "@/CAREUI/display/Callout";

const MESSAGE_KEYS = {
  add: "max_datapoints_per_upsert_limit",
  select: "max_deliveries_selected_limit",
} as const;

interface UpsertLimitCalloutProps {
  message?: keyof typeof MESSAGE_KEYS;
}

export default function UpsertLimitCallout({
  message = "add",
}: UpsertLimitCalloutProps) {
  const { t } = useTranslation();

  return (
    <Callout
      variant="warning"
      badge={<TriangleAlert className="size-4 shrink-0" />}
    >
      <span className="flex items-center gap-2">
        {t(MESSAGE_KEYS[message], {
          count: careConfig.maxDatapointsPerUpsert,
        })}
      </span>
    </Callout>
  );
}
"}

